func (this *Control) updateOrientation_() {
	var bits int32 = win32.OSGetWindowLong(this.Handle, win32.OSGWL_EXSTYLE)
	if (this.style & RIGHT_TO_LEFT) != 0 {
		bits |= win32.OSWS_EX_LAYOUTRTL
	} else {
		bits &= ^win32.OSWS_EX_LAYOUTRTL
	}
	bits &= ^win32.OSWS_EX_RTLREADING
	win32.OSSetWindowLong(this.Handle, win32.OSGWL_EXSTYLE, bits)
	win32.OSInvalidateRect(this.Handle, nil, true)
}

func (this *Control) UpdateTextDirection(textDirection int32) bool {
	return this.impl.updateTextDirection_(textDirection)
}

func (this *Control) updateTextDirection_(textDirection int32) bool {
	if textDirection == WidgetAUTO_TEXT_DIRECTION {
		textDirection = this.impl.resolveTextDirection_()
		this.state |= WidgetHAS_AUTO_DIRECTION
	} else {
		this.state &= ^WidgetHAS_AUTO_DIRECTION
	}
	if textDirection == 0 {
		return false
	}
	var bits int32 = win32.OSGetWindowLong(this.Handle, win32.OSGWL_EXSTYLE)
	var flags int32 = win32.OSWS_EX_LAYOUTRTL | win32.OSWS_EX_RTLREADING
	var oldRtl bool = ((bits&flags) != 0 && (bits&flags) != flags)
	var newRtl bool = textDirection == RIGHT_TO_LEFT
	if newRtl == oldRtl {
		return false
	}
	oldRtl = (bits & win32.OSWS_EX_LAYOUTRTL) != 0
	if newRtl != oldRtl {
		bits |= win32.OSWS_EX_RTLREADING
		this.style |= FLIP_TEXT_DIRECTION
	} else {
		bits &= ^win32.OSWS_EX_RTLREADING
		this.style &= ^FLIP_TEXT_DIRECTION
	}
	win32.OSSetWindowLong(this.Handle, win32.OSGWL_EXSTYLE, bits)
	win32.OSInvalidateRect(this.Handle, nil, true)
	return true
}

