func (this *Control) widgetExtStyle_() int32 {
	var bits int32 = 0
	if !this.impl.isUseWsBorder_() {
		if (this.style & BORDER) != 0 {
			bits |= win32.OSWS_EX_CLIENTEDGE
		}
	}
	bits |= win32.OSWS_EX_NOINHERITLAYOUT
	if (this.style & RIGHT_TO_LEFT) != 0 {
		bits |= win32.OSWS_EX_LAYOUTRTL
	}
	if (this.style & FLIP_TEXT_DIRECTION) != 0 {
		bits |= win32.OSWS_EX_RTLREADING
	}
	return bits
}

