func (this *Control) SetParent(parentLike CompositeLike) bool {
	var parent *Composite
	if parentLike != nil {
		parent = parentLike.AsComposite()
	}
	return this.impl.setParent_(parent)
}

func (this *Control) setParent_(parent *Composite) bool {
	this.CheckWidget()
	if parent == (nil) {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	if parent.IsDisposed() {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	if this.parent == parent {
		return true
	}
	if !this.impl.isReparentable_() {
		return false
	}
	this.impl.releaseParent_()
	var newShell *Shell = parent.impl.getShell_()
	var oldShell *Shell = this.impl.getShell_()
	var newDecorations *Decorations = parent.impl.menuShell_()
	var oldDecorations *Decorations = this.impl.menuShell_()
	if oldShell != newShell || oldDecorations != newDecorations {
		var menus []*Menu = oldShell.impl.findMenus_(this)
		this.impl.fixChildren_(newShell, oldShell, newDecorations, oldDecorations, menus)
	}
	var topHandle int64 = this.impl.topHandle_()
	if win32.OSSetParent(topHandle, parent.Handle) == 0 {
		return false
	}
	this.parent = parent
	var newZoom int32 = parent.NativeZoom
	if newZoom != this.NativeZoom {
		var zoomChangedEvent *Event = this.CreateZoomChangedEvent(newZoom, false)
		this.SendZoomChangedEvent(zoomChangedEvent, this.impl.getShell_())
	}
	var flags int32 = win32.OSSWP_NOSIZE | win32.OSSWP_NOMOVE | win32.OSSWP_NOACTIVATE
	win32.OSSetWindowPos(topHandle, int64(win32.OSHWND_BOTTOM), 0, 0, 0, 0, flags)
	this.impl.reskin_(ALL)
	return true
}

